using EventFlow.Operations.Application.Contracts;using EventFlow.Operations.Application.Features.AttendanceStaff;using EventFlow.Security.Authentication;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace EventFlow.Operations.Api.Controllers;
[Authorize,ApiController,Route("api/v1/operations/events/{eventId:guid}/attendance-staff")]
public sealed class AttendanceStaffController(AttendanceStaffService s,ICurrentUserService u):ControllerBase{[HttpGet]public async Task<IActionResult>List(Guid eventId,CancellationToken c){var r=await s.ListAsync(eventId,u.UserId,c);return Ok(r);}[HttpPost]public async Task<IActionResult>Assign(Guid eventId,AssignAttendanceStaffRequest q,CancellationToken c){var r=await s.AssignAsync(eventId,u.UserId,q,c);return r.IsSuccess?Ok(r):BadRequest(r);}[HttpDelete("{assignmentId:guid}")]public async Task<IActionResult>Revoke(Guid eventId,Guid assignmentId,CancellationToken c){var r=await s.RevokeAsync(eventId,assignmentId,u.UserId,c);return r.IsSuccess?Ok(r):BadRequest(r);}}
